{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "FK788, the closest analogue sharing the aryloxyacetic acid motif, showed 55% oral bioavailability in healthy volunteers, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Cicaprost, a prostacyclin analogue with a carboxylic acid and cyclopentane core, showed complete oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Iloprost, another prostacyclin analogue, showed absolute oral bioavailability of 56–63% in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Warfarin, an acidic drug, is nearly completely bioavailable orally, showing that acidic ionization alone does not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Pentopril, a carboxylic acid-containing drug, had 60–70% oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "2,4-D, an aryloxyacetic acid, showed rapid and complete oral bioavailability in humans, supporting high F for the aryloxyacetic acid query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Pravastatin, an acidic statin, had only about 17% oral bioavailability in humans, providing a contradictory low-F example, but its different scaffold and transporter-mediated disposition limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite an unfavorable ionization-based permeability prior, multiple human oral bioavailability data from structurally related aryloxyacetic acids and prostacyclin analogues (FK788 55%, cicaprost complete, iloprost 56–63%, pentopril 60–70%, 2,4-D complete) support F ≥ 20%. The main contradictory example, pravastatin (~17%), is less transferable due to its different scaffold and hepatic/transporter handling. Overall prediction: high.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "No fed-state-specific bioavailability data among the analogues; the fed condition may alter absorption but is not directly addressed.",
    "Analogues have low Morgan similarity (0.23–0.30), so transfer relies on chemical and biological analogy rather than high structural identity.",
    "Propafenone data are variable and not emphasized because the query is acidic rather than basic and lacks the same first-pass liability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

